using AcxiomCRM.Data;using AcxiomCRM.Models;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;namespace AcxiomCRM.Controllers;[Authorize(Roles="Admin,Manager")]public class ReportsController(AppDbContext db, UserManager<AppUser> users):Controller{public async Task<IActionResult> Index(){var uid=users.GetUserId(User);if(string.IsNullOrEmpty(uid))return Challenge();var admin=User.IsInRole("Admin");var team=users.Users.Where(u=>u.ManagerId==uid).Select(u=>u.Id);var stageAmounts=await db.Opportunities.Where(x=>admin||x.OwnerId==uid||team.Contains(x.OwnerId)).Select(x=>new {x.Stage,x.Amount}).ToListAsync();ViewBag.ByStage=stageAmounts.GroupBy(x=>x.Stage).Select(x=>new {Stage=x.Key,Count=x.Count(),Value=x.Sum(y=>y.Amount)}).ToList();return View();}}